    result = self.aggregate(
        0, 4 * HOUR, "hour", address="alice", method="transfer"
    )
    # a: alice→bob transfer; b: approve 排除; c: bob→alice transfer;
    # d: dave→alice transfer
    self.assertEqual(
        [b["total_count"] for b in result["buckets"]], [1, 1, 1, 0]
    )

